import type { Section } from "@/lib/types";
import { getSettings } from "@/lib/data";
import { Hero, type HeroImage } from "./Hero";
import { FeaturedProject } from "./FeaturedProject";
import { ProjectGrid } from "./ProjectGrid";
import { ServicesList } from "./ServicesList";
import { PromiseList, ShortText } from "./TextSections";
import { Process } from "./Process";
import { Comparison } from "./Comparison";
import { CallToAction } from "./CallToAction";
import { Showreel } from "./Showreel";

/** Spacing wrapper between page sections. */
export function Block({ children, className = "" }: { children: React.ReactNode; className?: string }) {
  return <section className={`mt-section first:mt-0 [[data-band]+&]:mt-after-band ${className}`}>{children}</section>;
}

/** Per-page presentation choices; the content always comes from the CMS. */
export type PageLayout = {
  /** Services as plain rows, group cards then service cards, or each group's card beside its services. */
  services?: "rows" | "directory" | "groups";
  /** One call-to-action card, or two side by side. */
  cta?: "single" | "dual";
  /** The first hero fills the screen (Home). */
  heroFull?: boolean;
  /** The first hero has the colour glow and our character behind its heading (Home). */
  heroGlow?: boolean;
  /** The first hero has the colour glow behind its heading, without the character. */
  heroLight?: boolean;
  /** The first hero's heading gets a little more room between its lines on phones (Services). */
  heroRoomy?: boolean;
  /** A picture for the first hero (Home). */
  heroImage?: HeroImage;
};

/**
 * Renders a page's CMS sections in order. A hero followed directly by a
 * featured project share one grey band, as in the reference.
 * `after` renders right after the first hero (used for the contact form).
 */
export async function SectionRenderer({
  sections,
  after,
  layout = {},
}: {
  sections: Section[];
  after?: React.ReactNode;
  layout?: PageLayout;
}) {
  const settings = await getSettings();
  const out: React.ReactNode[] = [];
  let afterPlaced = false;
  // Projects already shown big on this page (featured cards), so a grid of
  // latest work below them doesn't repeat them.
  const featured = sections.flatMap((s) => (s._type === "featuredProject" && s.project ? [s.project.slug] : []));

  for (let i = 0; i < sections.length; i++) {
    const section = sections[i];
    const next = sections[i + 1];
    switch (section._type) {
      case "hero": {
        // A featured project or the video card right after the hero shares the hero's band, close under it
        // (Home: the showreel since 18 Nov, in the place the featured project had).
        if (next?._type === "featuredProject" || next?._type === "showreel") {
          out.push(
            <section key={section._key} data-band>
              <Hero section={section} full={layout.heroFull && i === 0} glow={layout.heroGlow && i === 0} light={layout.heroLight && i === 0} roomy={layout.heroRoomy && i === 0} image={i === 0 ? layout.heroImage : undefined}>
                {next._type === "featuredProject" ? (
                  <FeaturedProject project={next.project} priority={!layout.heroFull && !layout.heroImage} />
                ) : (
                  // Home: the reel's poster is in the first screen (its top edge on computers, all of it on phones,
                  // where it is the largest thing shown), so it loads first unless the hero has its own image.
                  <Showreel section={next} priority={!layout.heroImage} />
                )}
              </Hero>
            </section>,
          );
          i++;
        } else {
          out.push(
            <section key={section._key} data-band>
              <Hero section={section} full={layout.heroFull && i === 0} glow={layout.heroGlow && i === 0} light={layout.heroLight && i === 0} roomy={layout.heroRoomy && i === 0} image={i === 0 ? layout.heroImage : undefined} />
            </section>,
          );
        }
        if (after && !afterPlaced) {
          out.push(<div key="after">{after}</div>);
          afterPlaced = true;
        }
        break;
      }
      case "featuredProject":
        out.push(
          <Block key={section._key}>
            <FeaturedProject project={section.project} priority={false} />
          </Block>,
        );
        break;
      case "projectGrid":
        out.push(
          <Block key={section._key}>
            <ProjectGrid section={section} exclude={featured} />
          </Block>,
        );
        break;
      case "servicesList":
        out.push(
          <Block key={section._key}>
            <ServicesList section={section} variant={layout.services} />
          </Block>,
        );
        break;
      case "shortText":
        out.push(
          <Block key={section._key}>
            <ShortText section={section} />
          </Block>,
        );
        break;
      case "promiseList":
        out.push(
          <Block key={section._key}>
            <PromiseList section={section} />
          </Block>,
        );
        break;
      case "process":
        out.push(
          <Block key={section._key}>
            <Process section={section} />
          </Block>,
        );
        break;
      case "comparison":
        out.push(
          <Block key={section._key}>
            <Comparison section={section} />
          </Block>,
        );
        break;
      case "showreel":
        out.push(
          <Block key={section._key}>
            <Showreel section={section} />
          </Block>,
        );
        break;
      case "callToAction":
        out.push(
          <Block key={section._key}>
            <CallToAction cta={settings.cta} variant={layout.cta} />
          </Block>,
        );
        break;
    }
  }

  if (after && !afterPlaced) out.unshift(<div key="after">{after}</div>);
  return <>{out}</>;
}
